/**
 * Split raw stdin text into lines, dropping the empty tail a trailing
 * newline leaves.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Split a flat list of lines into documents separated by lines that are
 * exactly `%%%`. Throws if the result is not exactly three documents.
 */
export function splitDocuments(lines) {
  const parts = []
  let current = []
  for (const line of lines) {
    if (line === '%%%') {
      parts.push(current)
      current = []
    } else {
      current.push(line)
    }
  }
  parts.push(current)
  if (parts.length !== 3) throw new Error('expected three parts separated by %%%')
  return parts
}
"}

