{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, comparing them as exact
 * strings, with a deterministic tie-break: when two subsequences are
 * equally long, prefer the one whose matches come earliest.
 */

/**
 * Compute the changes needed to turn `base` into `side`, as a list of runs
 * ordered by where they start in `base`. Each change is
 * `{ baseStart, baseEnd, sideStart, sideEnd }`, a half-open range of base
 * lines replaced by a half-open range of side lines. An insertion has
 * `baseStart === baseEnd`; a deletion has `sideStart === sideEnd`.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const next = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        row[j] = 1 + next[j + 1]
      } else {
        const a = next[j]
        const b = row[j + 1]
        row[j] = a >= b ? a : b
      }
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let runStartBase = 0
  let runStartSide = 0

  const flush = (endBase, endSide) => {
    if (endBase > runStartBase || endSide > runStartSide) {
      changes.push({ baseStart: runStartBase, baseEnd: endBase, sideStart: runStartSide, sideEnd: endSide })
    }
  }

  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(i, j)
      i++
      j++
      runStartBase = i
      runStartSide = j
    } else if (j >= m || (i < n && dp[i + 1][j] >= dp[i][j + 1])) {
      i++
    } else {
      j++
    }
  }
  flush(n, m)

  return changes
}
"}

