{"file_path":"src/merge.js","content":"import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Build a function mapping a base line index (at a boundary between
 * changes, never strictly inside one) to the corresponding index in the
 * side document that these changes were computed against.
 */
function makeMapper(changes) {
  return function (baseIdx) {
    let runningBase = 0
    let runningSide = 0
    for (const c of changes) {
      if (baseIdx <= c.baseStart) return runningSide + (baseIdx - runningBase)
      runningBase = c.baseEnd
      runningSide = c.sideEnd
    }
    return runningSide + (baseIdx - runningBase)
  }
}

/**
 * Group the changes from both sides into regions: contiguous stretches of
 * the base that one or more changes touch, absorbing overlapping changes
 * from either side.
 */
function computeRegions(changesMine, changesTheirs) {
  const combined = []
  for (const c of changesMine) combined.push({ ...c, side: 'mine' })
  for (const c of changesTheirs) combined.push({ ...c, side: 'theirs' })
  combined.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < combined.length) {
    let start = combined[idx].baseStart
    let end = combined[idx].baseEnd
    idx++
    while (idx < combined.length && combined[idx].baseStart <= end) {
      if (combined[idx].baseEnd > end) end = combined[idx].baseEnd
      idx++
    }
    regions.push({ baseStart: start, baseEnd: end })
  }
  return regions
}

/**
 * Compute the full merge plan: an ordered list of segments, each either a
 * stable base run or a region with its resolution.
 *
 * Each segment is one of:
 * - `{ kind: 'stable', lines }`
 * - `{ kind: 'mine' | 'theirs' | 'both', lines }`
 * - `{ kind: 'conflict', mine, base, theirs }`
 */
export function plan(mine, base, theirs) {
  const changesMine = computeChanges(base, mine)
  const changesTheirs = computeChanges(base, theirs)
  const mapMine = makeMapper(changesMine)
  const mapTheirs = makeMapper(changesTheirs)
  const regions = computeRegions(changesMine, changesTheirs)

  const segments = []
  let pos = 0

  const pushStable = (end) => {
    if (end > pos) segments.push({ kind: 'stable', lines: base.slice(pos, end) })
  }

  for (const region of regions) {
    pushStable(region.baseStart)

    const baseLines = base.slice(region.baseStart, region.baseEnd)
    const mineLines = mine.slice(mapMine(region.baseStart), mapMine(region.baseEnd))
    const theirsLines = theirs.slice(mapTheirs(region.baseStart), mapTheirs(region.baseEnd))

    const mineChanged = !arraysEqual(mineLines, baseLines)
    const theirsChanged = !arraysEqual(theirsLines, baseLines)

    if (!mineChanged && !theirsChanged) {
      segments.push({ kind: 'stable', lines: baseLines })
    } else if (!mineChanged) {
      segments.push({ kind: 'theirs', lines: theirsLines })
    } else if (!theirsChanged) {
      segments.push({ kind: 'mine', lines: mineLines })
    } else if (arraysEqual(mineLines, theirsLines)) {
      segments.push({ kind: 'both', lines: mineLines })
    } else {
      segments.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    pos = region.baseEnd
  }
  pushStable(base.length)

  return segments
